  //fileValidation before Upload(size and file type check)
  fileValidation() {
    this.isMediaFile = false;
    if (this.selectedFile) {
      let fileSize = this.selectedFile.size / 1048576;
      let extension = this.selectedFile.name.substring(this.selectedFile.name.lastIndexOf('.'));
      let allowedExtensions = this.fileExtensions;
      let allowedMediaExtension = this.mediaFileExtensions;
      if (this.selectedFile.name.length > 150) {
        return {
          'invalidFileName': true
        };
      }
      if (!allowedExtensions.includes(extension.toLowerCase())) {
        return {
          'invalidExtension': true
        };
      } else {
        if (fileSize > 10000) {
          return {
            'invalidMediaSize': true
          };
        } else if (fileSize <= 100 && !allowedMediaExtension.includes(extension.toLowerCase())) {
          return null;
        } else {
          if (allowedMediaExtension.includes(extension.toLowerCase())) {
            this.isMediaFile = true;
            return null;
          } else {
            return {
              'invalidSize': true
            };
          }
        }
      }
    }
    return null;
  }
